  { id: 'char-l3-m-51-2', type: 'mystery', characterId: 'haggai', category: 'Personnages', difficulty: 'expert', answer: 'Aggée', clues: ['Je reçois des messages de Jéhovah concernant la reconstruction du temple.','J’ai encouragé les Juifs à reprendre les travaux du temple.','J’ai aidé le peuple à examiner ses priorités.'], explanation: 'Ce personnage aida le peuple à examiner ses priorités.', reference: 'Aggée 1:1-15' },
  { id: 'char-l3-m-52-1', type: 'mystery', characterId: 'zechariah', category: 'Personnages', difficulty: 'hard', answer: 'Zacharie', clues: ['Ce personnage était un prophète contemporain d’Aggée qui encouragea les Juifs revenus d’exil à achever le temple et leur donna plusieurs visions prophétiques.','Jérusalem et Juda après l’exil.','Courage'], explanation: 'Ce personnage encouragea un peuple découragé à reprendre confiance dans le projet de reconstruction.', reference: 'Zacharie 1:1-21' },
  { id: 'char-l3-m-52-2', type: 'mystery', characterId: 'zechariah', category: 'Personnages', difficulty: 'expert', answer: 'Zacharie', clues: ['Il appelle le peuple à revenir vers Jéhovah.', 'reçut des visions et transmit les encouragements de Jéhovah aux Juifs revenus d’exil.', 'encouragea un peuple découragé à reprendre confiance dans le projet de reconstruction.'], explanation: 'Ce personnage encouragea un peuple découragé à reprendre confiance dans le projet de reconstruction.', reference: 'Zacharie 1:1-21' },
  { id: 'char-l3-m-53-1', type: 'mystery', characterId: 'malachi', category: 'Personnages', difficulty: 'hard', answer: 'Malachie', clues: ['Ce personnage était un prophète qui reprit les prêtres et le peuple de Juda pour leur manque de respect envers le culte de Jéhovah.','Juda et Jérusalem après l’exil.','Courage'], explanation: 'Ce personnage dénonça une adoration devenue mécanique et irrespectueuse.', reference: 'Malachie 1:1-14' },
  { id: 'char-l3-m-53-2', type: 'mystery', characterId: 'malachi', category: 'Personnages', difficulty: 'expert', answer: 'Malachie', clues: ['Il transmet plusieurs dialogues entre Jéhovah et son peuple.','Ce personnage défendit le culte pur et rappela aux prêtres et au peuple qu’ils devaient honorer Jéhovah avec sincérité plutôt que lui offrir un service négligent.','Ce personnage dénonça une adoration devenue mécanique et irrespectueuse.'], explanation: 'Ce personnage dénonça une adoration devenue mécanique et irrespectueuse.', reference: 'Malachie 1:1-14' },
  { id: 'char-l3-m-54-1', type: 'mystery', characterId: 'gamaliel', category: 'Personnages', difficulty: 'hard', answer: 'Gamaliel', clues: ['Ce personnage était un pharisien et enseignant de la Loi très respecté qui intervint lorsque les apôtres furent amenés devant le Sanhédrin.','Jérusalem.','Prudence'], explanation: 'Ce personnage était reconnu comme enseignant de la Loi parmi les Juifs.', reference: 'Actes 5:33-42' },
  { id: 'char-l3-m-54-2', type: 'mystery', characterId: 'gamaliel', category: 'Personnages', difficulty: 'expert', answer: 'Gamaliel', clues: ['Il demande que les apôtres soient sortis de la salle.', 'était un pharisien et un enseignant de la Loi.', 'était reconnu comme enseignant de la Loi parmi les Juifs.'], explanation: 'Ce personnage était reconnu comme enseignant de la Loi parmi les Juifs.', reference: 'Actes 5:33-42' },
  { id: 'char-l3-m-55-1', type: 'mystery', characterId: 'apollos', category: 'Personnages', difficulty: 'hard', answer: 'Apollos', clues: ['Ce personnage était un Juif instruit d’Alexandrie, éloquent et fervent, qui enseignait Jésus avec exactitude mais ne connaissait initialement que le baptême de Jean.','Éphèse, Corinthe et d’autres régions du bassin méditerranéen','Éloquence'], explanation: 'Ce personnage avait déjà une excellente connaissance des Écritures avant de recevoir des explications supplémentaires.', reference: 'Actes 18:24-28' },
  { id: 'char-l3-m-55-2', type: 'mystery', characterId: 'apollos', category: 'Personnages', difficulty: 'expert', answer: 'Apollos', clues: ['Il parle avec assurance dans la synagogue d’Éphèse.','Ce personnage connaissait déjà les Écritures et parlait avec ferveur au sujet de Jésus. Aquilas et Priscille lui expliquèrent plus exactement la voie de Dieu, et il accepta cette aide.','Ce personnage avait déjà une excellente connaissance des Écritures avant de recevoir des explications supplémentaires.'], explanation: 'Ce personnage avait déjà une excellente connaissance des Écritures avant de recevoir des explications supplémentaires.', reference: 'Actes 18:24-28' },
  { id: 'char-l3-m-56-1', type: 'mystery', characterId: 'silas', category: 'Personnages', difficulty: 'hard', answer: 'Silas', clues: ['Ce personnage, aussi appelé Silvain dans les lettres chrétiennes, était un membre éminent de la congrégation de Jérusalem, prophète et compagnon de voyage de Paul.','Jérusalem, Antioche de Syrie, Macédoine et Grèce.','Courage'], explanation: 'Ce personnage fut choisi pour accompagner Paul après avoir été recommandé par les responsables de Jérusalem.', reference: 'Actes 15:22-40' },
  { id: 'char-l3-m-56-2', type: 'mystery', characterId: 'silas', category: 'Personnages', difficulty: 'expert', answer: 'Silas', clues: ['Il est choisi par la congrégation de Jérusalem pour accompagner Paul et Barnabé.','Ce personnage servit comme prophète et collaborateur de Paul. Même après avoir été battu et emprisonné à Philippes, il continua à louer Dieu et à servir.','Ce personnage fut choisi pour accompagner Paul après avoir été recommandé par les responsables de Jérusalem.'], explanation: 'Ce personnage fut choisi pour accompagner Paul après avoir été recommandé par les responsables de Jérusalem.', reference: 'Actes 15:22-40' },
  { id: 'char-l3-m-57-1', type: 'mystery', characterId: 'onesimus', category: 'Personnages', difficulty: 'hard', answer: 'Onésime', clues: ['Ce personnage était l’esclave de Philémon qui s’enfuit de sa maison de Colosses, rencontra Paul à Rome et devint chrétien. Paul le renvoya ensuite auprès de Philémon comme frère chrétien.','Colosses et Rome.','Transformation'], explanation: 'Ce personnage changea de vie après être devenu chrétien.', reference: 'Philémon 8-21' },
  { id: 'char-l3-m-57-2', type: 'mystery', characterId: 'onesimus', category: 'Personnages', difficulty: 'expert', answer: 'Onésime', clues: ['Il appartenait à la maisonnée de Philémon à Colosses.','Ce personnage devint chrétien après avoir rencontré Paul et fut ensuite présenté à Philémon comme un frère chrétien. Sa transformation montre l’effet de la bonne nouvelle sur sa vie.','Ce personnage changea de vie après être devenu chrétien.'], explanation: 'Ce personnage changea de vie après être devenu chrétien.', reference: 'Philémon 8-21' },
  { id: 'char-l3-m-58-1', type: 'mystery', characterId: 'philemon', category: 'Personnages', difficulty: 'hard', answer: 'Philémon', clues: ['Ce personnage était un chrétien de Colosses, ami et collaborateur de Paul, chez qui une congrégation se réunissait. Paul lui écrivit au sujet d’Onésime.','Colosses, en Asie Mineure.','Amour'], explanation: 'Ce personnage était un chrétien connu pour son amour et sa foi.', reference: 'Philémon 1-25' },
  { id: 'char-l3-m-58-2', type: 'mystery', characterId: 'philemon', category: 'Personnages', difficulty: 'expert', answer: 'Philémon', clues: ['Il est félicité pour son amour et sa foi.', 'était un chrétien dont la foi et l’amour étaient connus de Paul.', 'était un chrétien connu pour son amour et sa foi.'], explanation: 'Ce personnage était un chrétien connu pour son amour et sa foi.', reference: 'Philémon 1-25' },
  { id: 'char-l3-m-59-1', type: 'mystery', characterId: 'titus', category: 'Personnages', difficulty: 'hard', answer: 'Tite', clues: ['Ce personnage était un collaborateur et proche associé de Paul, chrétien d’origine grecque, à qui Paul confia des responsabilités importantes dans plusieurs congrégations.','Diverses régions missionnaires, notamment la Crète.','Fiabilité'], explanation: 'Ce personnage accompagna Paul dans son activité missionnaire.', reference: 'Galates 2:1-3' },
  { id: 'char-l3-m-59-2', type: 'mystery', characterId: 'titus', category: 'Personnages', difficulty: 'expert', answer: 'Tite', clues: ['Il accompagne Paul dans certaines activités missionnaires.','Ce personnage fut un collaborateur fiable de Paul et reçut des responsabilités importantes dans les congrégations. Paul le chargea notamment d’aider à mettre les choses en ordre en Crète.','Ce personnage accompagna Paul dans son activité missionnaire.'], explanation: 'Ce personnage accompagna Paul dans son activité missionnaire.', reference: 'Galates 2:1-3' },
  { id: 'char-l3-m-60-1', type: 'mystery', characterId: 'eutychus', category: 'Personnages', difficulty: 'hard', answer: 'Eutyche', clues: ['Jeune homme de Troas — Ce personnage est connu pour l’incident survenu pendant un long discours de Paul à Troas.','Troas, en Asie Mineure.','Attention aux enseignements chrétiens'], explanation: 'Ce personnage était présent à une longue réunion chrétienne.', reference: 'Actes 20:7-12' },
  { id: 'char-l3-m-60-2', type: 'mystery', characterId: 'eutychus', category: 'Personnages', difficulty: 'expert', answer: 'Eutyche', clues: ['Assiste à une réunion chrétienne à Troas.','L’événement autour de ce personnage fut un puissant témoignage de la puissance de Dieu et encouragea les disciples présents.','Ce personnage était présent à une longue réunion chrétienne.'], explanation: 'Ce personnage était présent à une longue réunion chrétienne.', reference: 'Actes 20:7-12' }
